<script lang="ts">
  import { onMount } from 'svelte'; import { convertFileSrc } from '@tauri-apps/api/core'; import { exportError, exportClip, exportStarted, lastExported, lastSaved, saveError, saveClip, listClips, showInFolder, type ClipEntry } from '$lib/daemon';
  let clips = $state<ClipEntry[]>([]); let query=$state(''); let sort=$state<'newest'|'name'>('newest'); let fps=$state('60'); let custom=$state(''); let clipLimit=$state(24);
  const refresh=async()=>{try{clips=await listClips(500)}catch{clips=[]}}; onMount(refresh); $effect(()=>{if($lastSaved||$lastExported) void refresh()});
  const filtered=$derived(clips.filter(c=>c.name.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):b.mtime-a.mtime)); const visible=$derived(filtered.slice(0,clipLimit)); const rate=$derived(fps==='custom'?Number(custom):Number(fps)); const valid=$derived(Number.isSafeInteger(rate)&&rate>0&&rate<=2147483647); const base=(p:string)=>p.split('\\').pop()??p; const mb=(v:number)=>(v/1048576).toFixed(1); const date=(v:number)=>new Date(v*1000).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}); const time=(v:number)=>new Date(v*1000).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}); const preview=(event:Event)=>{const video=event.currentTarget as HTMLVideoElement; void video.play().catch(()=>{})}; const stopPreview=(event:Event)=>{const video=event.currentTarget as HTMLVideoElement; video.pause(); video.currentTime=0}; const loadMore=()=>{clipLimit+=24};
  const save=(seconds?:number)=>saveClip(seconds).catch(e=>saveError.set(String(e))); const exportOne=(path:string)=>{if(!valid||$exportStarted)return;exportError.set(null);exportStarted.set({path:'',source:path,fps:rate,at:Date.now()});exportClip(path,rate).catch(e=>{exportStarted.set(null);exportError.set(String(e))})};
</script>
<div class="page-head"><div><h1>Clips <span>{clips.length}</span></h1><p>Saved replay footage</p></div><div class="save-actions"><button class="primary" onclick={()=>save()}>Save replay</button><button onclick={()=>save(30)}>30 s</button></div></div>
<div class="library-tools"><label>Search <input bind:value={query} placeholder="Find a clip"/></label><label>Sort <select bind:value={sort}><option value="newest">Newest first</option><option value="name">Filename</option></select></label><label>Export <select bind:value={fps}><option value="60">60 fps</option><option value="120">120 fps</option><option value="240">240 fps</option><option value="480">480 fps</option><option value="960">960 fps</option><option value="custom">Custom</option></select></label>{#if fps==='custom'}<input aria-label="Custom export FPS" bind:value={custom} type="number" min="1" max="2147483647" placeholder="fps"/>{/if}</div>
{#if $saveError}<p class="message fail">Save failed: {$saveError}</p>{/if}{#if $exportError}<p class="message fail">Export failed: {$exportError}</p>{/if}{#if $exportStarted}<p class="message">Exporting {base($exportStarted.source)} at {$exportStarted.fps} fps</p>{/if}{#if $lastExported}<p class="message good">Exported {base($lastExported.path)} · {$lastExported.frames} frames <button onclick={()=>showInFolder($lastExported.path)}>Reveal</button></p>{/if}
{#if visible.length}<section class="library" aria-label="Clip library">{#each visible as clip (clip.path)}<article><a class="thumb" href={`/editor?path=${encodeURIComponent(clip.path)}`}>{#if clip.thumb}<img src={convertFileSrc(clip.thumb)} alt={clip.name}/>{:else}<video src={convertFileSrc(clip.path)} muted playsinline preload="metadata" aria-label={`Preview of ${clip.name}`} onmouseenter={preview} onmouseleave={stopPreview} onfocus={preview} onblur={stopPreview}></video>{/if}</a><div class="clip-info"><a href={`/editor?path=${encodeURIComponent(clip.path)}`}>{clip.name}</a><small>{date(clip.mtime)} · {time(clip.mtime)} · {mb(clip.bytes)} MB</small><div><a class="edit" href={`/editor?path=${encodeURIComponent(clip.path)}`}>Edit</a><button onclick={()=>showInFolder(clip.path)}>Reveal</button><button disabled={!valid||!!$exportStarted} onclick={()=>exportOne(clip.path)}>Export</button></div></div></article>{/each}</section>{#if filtered.length > clipLimit}<div class="load-more"><button onclick={loadMore}>Load 24 more</button></div>{/if}{:else}<section class="empty"><h2>{clips.length?'No clips match this search':'No saved clips'}</h2><p>{clips.length?'Clear the search or change sorting.':'Save a replay while capture is ready. Saved clips remain editable while the recorder is offline.'}</p></section>{/if}
<style>
  h1{margin:0;font:650 24px/1 Bahnschrift,"Segoe UI Variable",sans-serif}h1 span{color:var(--muted);font-size:15px;font-weight:500;margin-left:6px}.page-head{display:flex;justify-content:space-between;gap:16px;align-items:start;border-bottom:1px solid var(--line);padding-bottom:16px}.page-head p{margin:5px 0 0;color:var(--muted);font-size:12px}.save-actions,.library-tools{display:flex;gap:8px;align-items:center}.library-tools{padding:14px 0;flex-wrap:wrap}.library-tools label{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:6px}button,select,input{border:1px solid var(--line);border-radius:var(--r4);background:var(--raised);color:var(--text);padding:7px 9px;font:13px/18px "Segoe UI",system-ui,sans-serif}button{cursor:pointer}button:hover:not(:disabled){border-color:var(--steel)}button:disabled{opacity:.5;cursor:not-allowed}.primary{background:#486f9b;border-color:#6f99c7;font-weight:600}.library{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:16px}.library article{background:var(--panel);border:1px solid var(--line);border-radius:var(--r8);overflow:hidden}.thumb{position:relative;display:block;aspect-ratio:16/9;overflow:hidden;background:#11151a;color:var(--muted);font-size:12px}.thumb img,.thumb video{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.thumb video{background:#11151a}.clip-info{padding:10px}.clip-info>a{display:block;color:var(--text);text-decoration:none;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.clip-info small{display:block;margin-top:4px;color:var(--muted);font-size:11px}.clip-info div{display:flex;gap:7px;margin-top:11px}.edit{color:var(--steel);font-size:12px;text-decoration:none;padding:7px 4px}.clip-info button{font-size:12px;padding:5px 7px}.message{margin:0 0 10px;padding:9px 10px;border-left:2px solid var(--steel);background:var(--panel);font-size:12px}.message.good{border-color:var(--mint)}.message.fail{border-color:var(--coral)}.message button{margin-left:8px;padding:3px 6px}.load-more{display:flex;justify-content:center;padding:20px 0}.empty{margin-top:28px;border-top:1px solid var(--line);padding:24px 0;color:var(--muted)}.empty h2{font-size:14px;color:var(--text)}@media(max-width:600px){.page-head{display:grid}.save-actions{width:100%}.library{grid-template-columns:1fr}}
</style>
